// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 600, H = 450;
draw.viewbox(0, 0, W, H);

var black = '#111111';
var blue = '#174a8b';
var teal = '#008b8b';
var warm = '#f4a11a';
var selectBlue = '#1b9aaa';

var a = { x: 80, y: 80 }, b = { x: 300, y: 80 }, c = { x: 520, y: 80 };
var f = { x: 80, y: 330 }, e = { x: 300, y: 330 }, d = { x: 520, y: 330 };

var base = draw.group();
var loopGroup = draw.group();
var junctionGroup = draw.group();
var labelsTop = draw.group();
var nodeGroup = draw.group();
var hitGroup = draw.group();

var currentViewLabeled = false;
var selectedJunction = null;
var currentLoopState = 'idle';
var stepIndex = 0;

function line(g, x1, y1, x2, y2, color, width, opacity) {
  return g.line(x1, y1, x2, y2).stroke({
    color: color || black,
    width: width || 2.4,
    linecap: 'round',
    linejoin: 'round',
    opacity: opacity == null ? 1 : opacity
  });
}

function polyPts(pts) {
  return pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
}

function zigH(g, x1, y, x2, color, width, opacity) {
  var n = 8, amp = 10, pts = [[x1, y]];
  var step = (x2 - x1) / n;
  for (var i = 1; i < n; i++) pts.push([x1 + i * step, y + (i % 2 ? -amp : amp)]);
  pts.push([x2, y]);
  return g.polyline(polyPts(pts)).fill('none').stroke({
    color: color || blue,
    width: width || 3.8,
    linecap: 'round',
    linejoin: 'round',
    opacity: opacity == null ? 1 : opacity
  });
}

function zigV(g, x, y1, y2, color, width, opacity) {
  var n = 8, amp = 10, pts = [[x, y1]];
  var step = (y2 - y1) / n;
  for (var i = 1; i < n; i++) pts.push([x + (i % 2 ? amp : -amp), y1 + i * step]);
  pts.push([x, y2]);
  return g.polyline(polyPts(pts)).fill('none').stroke({
    color: color || blue,
    width: width || 3.8,
    linecap: 'round',
    linejoin: 'round',
    opacity: opacity == null ? 1 : opacity
  });
}

function textHalo(g, s, x, y, size, opts) {
  opts = opts || {};
  var t = g.text(s).font({
    family: opts.family || 'Georgia, "Times New Roman", serif',
    size: size || 16,
    style: opts.italic ? 'italic' : 'normal'
  }).fill(opts.fill || '#111');
  t.attr({
    'paint-order': 'stroke',
    stroke: '#ffffff',
    'stroke-width': opts.halo == null ? 4 : opts.halo,
    'stroke-linejoin': 'round'
  });
  if (opts.anchor) t.attr({ 'text-anchor': opts.anchor });
  t.move(x, y);
  return t;
}

function battery(g, xLong, xShort, y, plusLeft) {
  var longTop = y - 24, longBot = y + 24, shortTop = y - 14, shortBot = y + 14;
  line(g, xLong, longTop, xLong, longBot, black, 2.4);
  line(g, xShort, shortTop, xShort, shortBot, black, 2.4);
  var plusX = plusLeft ? xLong - 14 : xShort + 8;
  var minusX = plusLeft ? xShort + 8 : xLong - 14;
  textHalo(g, '+', plusX, y - 34, 20, { family: 'Arial, sans-serif', halo: 3 });
  textHalo(g, '−', minusX, y - 35, 21, { family: 'Arial, sans-serif', halo: 3 });
}

function drawCircuit() {
  base.clear();
  labelsTop.clear();

  line(base, a.x, a.y, 120, 80);
  zigH(base, 120, 80, 180);
  line(base, 180, 80, b.x, b.y);

  line(base, b.x, b.y, 340, 80);
  zigH(base, 340, 80, 400);
  line(base, 400, 80, c.x, c.y);

  line(base, a.x, a.y, f.x, f.y);
  line(base, b.x, b.y, 300, 132);
  zigV(base, 300, 132, 205);
  line(base, 300, 205, e.x, e.y);

  line(base, c.x, c.y, 520, 132);
