  textHalo(labelsTop, 'R₁ = 3.00 Ω', 72, 23, 20);
  textHalo(labelsTop, 'R₃ = 3.00 Ω', 344, 23, 20);
  textHalo(labelsTop, 'R₂ = 3.00 Ω', 170, 139, 19);
  textHalo(labelsTop, 'R₄ = 4.00 Ω', 394, 139, 19);
  textHalo(labelsTop, 'V₁ = 24.00 V', 106, 282, 19, { anchor: 'middle' });
  textHalo(labelsTop, 'V₂ = 29.00 V', 365, 282, 19, { anchor: 'middle' });

