function highlightResistor(g, which, opacity) {
  opacity = opacity == null ? 0.9 : opacity;
  if (which === 'R1') zigH(g, 120, 80, 180, warm, 8, opacity);
  if (which === 'R2') zigV(g, 300, 132, 205, warm, 8, opacity);
