// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 900, H = 310;
draw.viewbox(0, 0, W, H);

var black = '#111111';
var blue = '#174a8b';
var teal = '#008b8b';
var warm = '#f4a11a';
var warmDark = '#c97800';

var baseGroup = draw.group();
var loopGroup = draw.group();
var junctionGroup = draw.group();
var emphasisGroup = draw.group();
var nodeGroup = draw.group();
var labelGroup = draw.group();
var hitGroup = draw.group();

var panels = {
  left: { L: 2, M: 202, R: 408, T: 42, B: 252, label: '(a)' },
  right: { L: 480, M: 680, R: 886, T: 42, B: 252, label: '(b)' }
};

var currentLoopState = 'idle';
var selectedJunction = null;
var emphasisOn = false;
var stepIndex = 0;

function line(g, x1, y1, x2, y2, color, width, opacity) {
  return g.line(x1, y1, x2, y2).stroke({
    color: color || black,
    width: width || 2.3,
    linecap: 'round',
    linejoin: 'round',
    opacity: opacity == null ? 1 : opacity
  });
}

function ptsAttr(pts) {
  return pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
}

function zigH(g, x1, y, x2, color, width, opacity) {
  var n = 9, amp = 8.5, pts = [[x1, y]];
  var step = (x2 - x1) / n;
  for (var i = 1; i < n; i++) pts.push([x1 + i * step, y + (i % 2 ? -amp : amp)]);
  pts.push([x2, y]);
  return g.polyline(ptsAttr(pts)).fill('none').stroke({
    color: color || blue,
    width: width || 3.7,
    linecap: 'round',
    linejoin: 'round',
    opacity: opacity == null ? 1 : opacity
  });
}

function zigV(g, x, y1, y2, color, width, opacity) {
  var n = 9, amp = 8.5, pts = [[x, y1]];
  var step = (y2 - y1) / n;
  for (var i = 1; i < n; i++) pts.push([x + (i % 2 ? amp : -amp), y1 + i * step]);
  pts.push([x, y2]);
  return g.polyline(ptsAttr(pts)).fill('none').stroke({
    color: color || blue,
    width: width || 3.7,
    linecap: 'round',
    linejoin: 'round',
    opacity: opacity == null ? 1 : opacity
  });
}

function textHalo(g, s, x, y, size, opts) {
  opts = opts || {};
  var t = g.text(s).font({
    family: opts.family || 'Georgia, "Times New Roman", serif',
    size: size || 17,
    style: opts.italic ? 'italic' : 'normal'
  }).fill(opts.fill || '#111');
  t.attr({
    'paint-order': 'stroke',
    stroke: opts.stroke || '#ffffff',
    'stroke-width': opts.halo == null ? 3.2 : opts.halo,
    'stroke-linejoin': 'round'
  });
  if (opts.anchor) t.attr({ 'text-anchor': opts.anchor });
  t.move(x, y);
  return t;
}

function battery(g, p, leftPlateX, rightPlateX, longOnLeft) {
  var y = p.B;
  var longTop = y - 24, longBot = y + 18;
  var shortTop = y - 15, shortBot = y + 9;
  var longX = longOnLeft ? leftPlateX : rightPlateX;
  var shortX = longOnLeft ? rightPlateX : leftPlateX;

  line(g, leftPlateX - 24, y, leftPlateX - 5, y, black, 2.3);
  line(g, rightPlateX + 5, y, rightPlateX + 45, y, black, 2.3);
  line(g, longX, longTop, longX, longBot, black, 2.3);
  line(g, shortX, shortTop, shortX, shortBot, black, 2.3);

  if (longOnLeft) {
    textHalo(g, '+', longX - 20, y - 20, 18, { family: 'Arial, sans-serif', halo: 2.4 });
    textHalo(g, '−', shortX + 10, y - 22, 18, { family: 'Arial, sans-serif', halo: 2.4 });
  } else {
    textHalo(g, '−', shortX - 19, y - 22, 18, { family: 'Arial, sans-serif', halo: 2.4 });
    textHalo(g, '+', longX + 9, y - 20, 18, { family: 'Arial, sans-serif', halo: 2.4 });
  }
}

function drawCircuit(p, labeled) {
  var L = p.L, M = p.M, R = p.R, T = p.T, B = p.B;

  var r1a = L + 52, r1b = L + 100;
  var r3a = M + 78, r3b = M + 124;
  var r2a = T + 48, r2b = T + 94;
  var r4a = T + 48, r4b = T + 94;

  line(baseGroup, L, T, r1a, T);
  zigH(baseGroup, r1a, T, r1b);
  line(baseGroup, r1b, T, M, T);

  line(baseGroup, M, T, r3a, T);
  zigH(baseGroup, r3a, T, r3b);
  line(baseGroup, r3b, T, R, T);

  line(baseGroup, L, T, L, B);
  line(baseGroup, M, T, M, r2a);
  zigV(baseGroup, M, r2a, r2b);
  line(baseGroup, M, r2b, M, B);

  line(baseGroup, R, T, R, r4a);
  zigV(baseGroup, R, r4a, r4b);
  line(baseGroup, R, r4b, R, B);

  line(baseGroup, L, B, L + 56, B);
  battery(baseGroup, p, L + 82, L + 94, true);
  line(baseGroup, L + 139, B, M, B);

  line(baseGroup, M, B, M + 84, B);
  battery(baseGroup, p, M + 98, M + 110, false);
  line(baseGroup, M + 155, B, R, B);

  textHalo(labelGroup, 'R₁ = 3.00 Ω', L + 21, T - 41, 18);
  textHalo(labelGroup, 'R₃ = 3.00 Ω', M + 46, T - 41, 18);
  textHalo(labelGroup, 'R₂ = 3.00 Ω', M - 124, T + 62, 18);
  textHalo(labelGroup, 'R₄ = 4.00 Ω', R - 126, T + 62, 18);
  textHalo(labelGroup, 'V₁ = 24.00 V', L + 32, B - 44, 18);
  textHalo(labelGroup, 'V₂ = 29.00 V', M + 40, B - 44, 18);
  textHalo(labelGroup, p.label, (L + R) / 2 - 8, B + 37, 18, { family: 'Arial, sans-serif' });

  if (labeled) drawNodesForPanel(p);
}

function drawNodesForPanel(p) {
  var nodes = [
    ['a', p.L, p.T, -12, -31],
    ['b', p.M, p.T, -7, -31],
    ['c', p.R, p.T, -5, -31],
    ['f', p.L, p.B, -5, 7],
    ['e', p.M, p.B, -7, 7],
    ['d', p.R, p.B, -10, 7]
  ];
  nodes.forEach(function (n) {
    var name = n[0], x = n[1], y = n[2];
    nodeGroup.circle(8.6).center(x, y).fill(teal).stroke('none');
    textHalo(nodeGroup, name, x + n[3], y + n[4], 18, { italic: true, halo: 3 });
  });
}

function coords(name) {
  var p = panels.right;
  if (name === 'a') return { x: p.L, y: p.T };
  if (name === 'b') return { x: p.M, y: p.T };
  if (name === 'c') return { x: p.R, y: p.T };
  if (name === 'f') return { x: p.L, y: p.B };
  if (name === 'e') return { x: p.M, y: p.B };
  return { x: p.R, y: p.B };
}

function arrow(g, x1, y1, x2, y2, label, lx, ly, color) {
  color = color || warmDark;
  line(g, x1, y1, x2, y2, color, 3, 1);
  var ang = Math.atan2(y2 - y1, x2 - x1);
  var s = 9;
  var p1 = [x2, y2];
  var p2 = [x2 - s * Math.cos(ang - 0.55), y2 - s * Math.sin(ang - 0.55)];
  var p3 = [x2 - s * Math.cos(ang + 0.55), y2 - s * Math.sin(ang + 0.55)];
  g.polygon(ptsAttr([p1, p2, p3])).fill(color).stroke('none');
  if (label) textHalo(g, label, lx, ly, 14, { family: 'Arial, sans-serif', halo: 3 });
}

function equationBox(g, txt, x, y, w) {
  var width = w || Math.max(142, txt.length * 7.2 + 22);
  var h = 31;
  g.rect(width, h).move(x, y).radius(5).fill('#fff8e8').stroke({ color: warm, width: 1.4 });
  textHalo(g, txt, x + 9, y + 7, 14, { family: 'Arial, sans-serif', halo: 2 });
}

function toggle_comparisonEmphasis(on) {
  emphasisOn = !!on;
  redrawEmphasis();
}

function redrawEmphasis() {
  emphasisGroup.clear();
  if (!emphasisOn) return;
  var p = panels.right;
  [['a', p.L, p.T], ['b', p.M, p.T], ['c', p.R, p.T], ['f', p.L, p.B], ['e', p.M, p.B], ['d', p.R, p.B]].forEach(function (n) {
    emphasisGroup.circle(25).center(n[1], n[2]).fill({ color: teal, opacity: 0.12 }).stroke({ color: teal, width: 1.4, opacity: 0.55 });
  });
  line(emphasisGroup, p.L, p.T, p.M, p.T, teal, 7, 0.10);
  line(emphasisGroup, p.M, p.T, p.R, p.T, teal, 7, 0.10);
  line(emphasisGroup, p.L, p.B, p.M, p.B, teal, 7, 0.10);
  line(emphasisGroup, p.M, p.B, p.R, p.B, teal, 7, 0.10);
  line(emphasisGroup, p.L, p.T, p.L, p.B, teal, 7, 0.10);
  line(emphasisGroup, p.M, p.T, p.M, p.B, teal, 7, 0.10);
  line(emphasisGroup, p.R, p.T, p.R, p.B, teal, 7, 0.10);
}

function selectJunction(name, silent) {
  selectedJunction = name;
  currentLoopState = 'idle';
  var sel = document.getElementById('loopTraceInput');
  if (sel) sel.value = 'idle';
  redrawLoop();
  redrawJunction();
  if (!silent) {
    showPopup('Kirchhoff junction rule', name === 'b'
      ? 'At node b, current entering from branch a-b equals the current leaving through branches b-c and b-e. The equation is I_ab = I_bc + I_be.'
      : 'At node e, the currents entering through b-e and f-e equal the current leaving toward d. The equation is I_be + I_fe = I_ed.');
  }
}

function redrawJunction() {
  junctionGroup.clear();
  if (!selectedJunction) return;
  var p = panels.right;
  var b = coords('b'), e = coords('e');
  var a = coords('a'), c = coords('c'), f = coords('f'), d = coords('d');
  var node = selectedJunction === 'b' ? b : e;
  junctionGroup.circle(34).center(node.x, node.y).fill('none').stroke({ color: teal, width: 4, opacity: 0.68 });

  if (selectedJunction === 'b') {
    line(junctionGroup, a.x, a.y, b.x, b.y, warm, 10, 0.20);
    line(junctionGroup, b.x, b.y, c.x, c.y, warm, 10, 0.20);
    line(junctionGroup, b.x, b.y, e.x, e.y, warm, 10, 0.20);
    arrow(junctionGroup, p.L + 112, p.T - 18, p.M - 28, p.T - 18, 'I_ab', p.L + 125, p.T - 42, teal);
    arrow(junctionGroup, p.M + 28, p.T - 18, p.M + 114, p.T - 18, 'I_bc', p.M + 45, p.T - 42, teal);
    arrow(junctionGroup, p.M + 22, p.T + 34, p.M + 22, p.T + 103, 'I_be', p.M + 28, p.T + 60, teal);
    equationBox(junctionGroup, 'I_ab = I_bc + I_be', p.M + 42, p.T + 92, 158);
  } else {
    line(junctionGroup, b.x, b.y, e.x, e.y, warm, 10, 0.20);
    line(junctionGroup, f.x, f.y, e.x, e.y, warm, 10, 0.20);
    line(junctionGroup, e.x, e.y, d.x, d.y, warm, 10, 0.20);
    arrow(junctionGroup, p.M + 22, p.T + 107, p.M + 22, p.B - 30, 'I_be', p.M + 28, p.T + 136, teal);
    arrow(junctionGroup, p.L + 92, p.B + 22, p.M - 35, p.B + 22, 'I_fe', p.L + 119, p.B + 25, teal);
    arrow(junctionGroup, p.M + 35, p.B + 22, p.M + 132, p.B + 22, 'I_ed', p.M + 66, p.B + 25, teal);
    equationBox(junctionGroup, 'I_be + I_fe = I_ed', p.M + 30, p.B - 83, 168);
  }
}

function highlightResistor(g, which, opacity) {
  var p = panels.right;
  opacity = opacity == null ? 0.9 : opacity;
  if (which === 'R1') zigH(g, p.L + 52, p.T, p.L + 100, warm, 8, opacity);
  if (which === 'R3') zigH(g, p.M + 78, p.T, p.M + 124, warm, 8, opacity);
  if (which === 'R2') zigV(g, p.M, p.T + 48, p.T + 94, warm, 8, opacity);
  if (which === 'R4') zigV(g, p.R, p.T + 48, p.T + 94, warm, 8, opacity);
}

function highlightBattery(g, which, opacity) {
  var p = panels.right;
  opacity = opacity == null ? 0.9 : opacity;
  if (which === 'V1') g.rect(39, 58).move(p.L + 71, p.B - 32).radius(4).fill('none').stroke({ color: warm, width: 5, opacity: opacity });
  if (which === 'V2') g.rect(39, 58).move(p.M + 88, p.B - 32).radius(4).fill('none').stroke({ color: warm, width: 5, opacity: opacity });
}

function loopPath(g, side) {
  var p = panels.right;
  var pts = side === 'left'
    ? [[p.L, p.T], [p.M, p.T], [p.M, p.B], [p.L, p.B], [p.L, p.T]]
    : [[p.M, p.T], [p.R, p.T], [p.R, p.B], [p.M, p.B], [p.M, p.T]];
  g.polyline(ptsAttr(pts)).fill('none').stroke({ color: warm, width: 10, opacity: 0.25, linejoin: 'round', linecap: 'round' });
  if (side === 'left') {
    arrow(g, p.L + 58, p.T + 20, p.M - 36, p.T + 20, '', 0, 0, warm);
    arrow(g, p.M - 22, p.T + 62, p.M - 22, p.B - 54, '', 0, 0, warm);
    arrow(g, p.M - 42, p.B - 22, p.L + 70, p.B - 22, '', 0, 0, warm);
    arrow(g, p.L + 23, p.B - 52, p.L + 23, p.T + 62, '', 0, 0, warm);
  } else {
    arrow(g, p.M + 58, p.T + 20, p.R - 40, p.T + 20, '', 0, 0, warm);
    arrow(g, p.R - 23, p.T + 62, p.R - 23, p.B - 54, '', 0, 0, warm);
    arrow(g, p.R - 55, p.B - 22, p.M + 72, p.B - 22, '', 0, 0, warm);
    arrow(g, p.M - 22, p.B - 58, p.M - 22, p.T + 64, '', 0, 0, warm);
  }
}

function redrawLoop() {
  loopGroup.clear();
  if (currentLoopState === 'idle') return;
  selectedJunction = null;
  junctionGroup.clear();

  var p = panels.right;
  var left = currentLoopState.indexOf('left') === 0;
  loopPath(loopGroup, left ? 'left' : 'right');

  if (currentLoopState === 'leftR1Drop') {
    highlightResistor(loopGroup, 'R1');
    equationBox(loopGroup, '−I_ab R₁', p.L + 72, p.T + 117, 100);
  } else if (currentLoopState === 'leftR2Drop') {
    highlightResistor(loopGroup, 'R2');
    equationBox(loopGroup, '−I_ab R₁ − I_be R₂', p.L + 55, p.T + 117, 175);
  } else if (currentLoopState === 'leftV1Rise') {
    highlightBattery(loopGroup, 'V1');
    equationBox(loopGroup, '−I_ab R₁ − I_be R₂ + V₁', p.L + 44, p.T + 117, 210);
  } else if (currentLoopState === 'leftEquation') {
    highlightResistor(loopGroup, 'R1', 0.58);
    highlightResistor(loopGroup, 'R2', 0.58);
    highlightBattery(loopGroup, 'V1', 0.58);
    equationBox(loopGroup, '−I_ab R₁ − I_be R₂ + V₁ = 0', p.L + 35, p.T + 117, 247);
  } else if (currentLoopState === 'rightR3Drop') {
    highlightResistor(loopGroup, 'R3');
    equationBox(loopGroup, '−I_bc R₃', p.M + 68, p.T + 117, 100);
  } else if (currentLoopState === 'rightR4Drop') {
    highlightResistor(loopGroup, 'R4');
    equationBox(loopGroup, '−I_bc R₃ − I_cd R₄', p.M + 45, p.T + 117, 180);
  } else if (currentLoopState === 'rightV2Drop') {
    highlightBattery(loopGroup, 'V2');
    equationBox(loopGroup, '−I_bc R₃ − I_cd R₄ − V₂', p.M + 31, p.T + 117, 225);
  } else if (currentLoopState === 'rightR2Opposite') {
    highlightResistor(loopGroup, 'R2');
    equationBox(loopGroup, '−I_bc R₃ − I_cd R₄ − V₂ + I_be R₂', p.M - 63, p.T + 117, 315);
  } else if (currentLoopState === 'rightEquation') {
    highlightResistor(loopGroup, 'R3', 0.58);
    highlightResistor(loopGroup, 'R4', 0.58);
    highlightBattery(loopGroup, 'V2', 0.58);
    highlightResistor(loopGroup, 'R2', 0.58);
    equationBox(loopGroup, '−I_bc R₃ − I_cd R₄ − V₂ + I_be R₂ = 0', p.M - 82, p.T + 117, 356);
  }

  if (left) {
    arrow(loopGroup, p.L + 110, p.T - 19, p.M - 33, p.T - 19, 'I_ab', p.L + 129, p.T - 42, warmDark);
    arrow(loopGroup, p.M + 21, p.T + 40, p.M + 21, p.B - 44, 'I_be', p.M + 27, p.T + 78, warmDark);
  } else {
    arrow(loopGroup, p.M + 45, p.T - 19, p.M + 135, p.T - 19, 'I_bc', p.M + 63, p.T - 42, warmDark);
    arrow(loopGroup, p.R + 19, p.T + 52, p.R + 19, p.T + 128, 'I_cd', p.R + 25, p.T + 76, warmDark);
    arrow(loopGroup, p.M + 21, p.T + 133, p.M + 21, p.T + 58, 'opposite I_be', p.M + 27, p.T + 93, warmDark);
  }
}

function update_loopTrace(v) {
  currentLoopState = v;
  var sel = document.getElementById('loopTraceInput');
  if (sel) sel.value = v;
  redrawLoop();
}

function trigger_selectB() { selectJunction('b'); }
function trigger_selectE() { selectJunction('e'); }

function trigger_traceLeft() {
  document.getElementById('comparisonEmphasisInput').checked = true;
  toggle_comparisonEmphasis(true);
  update_loopTrace('leftEquation');
}

function trigger_traceRight() {
  document.getElementById('comparisonEmphasisInput').checked = true;
  toggle_comparisonEmphasis(true);
  update_loopTrace('rightEquation');
}

function trigger_clearLoop() {
  selectedJunction = null;
  junctionGroup.clear();
  update_loopTrace('idle');
}

function makeNodeHit(name) {
  var p = coords(name);
  hitGroup.circle(42).center(p.x, p.y).fill({ color: '#ffffff', opacity: 0.001 }).stroke('none')
    .css('cursor', 'pointer')
    .on('mousemove', function (ev) {
      if (name === 'b' || name === 'e') showTooltip('Click node ' + name + ' to apply the junction rule.', ev);
      else showTooltip('Node ' + name + ': a labeled circuit point used for Kirchhoff analysis.', ev);
    })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      if (name === 'b' || name === 'e') selectJunction(name);
